  "a_sentences": [
    {
      "a_text": "Le Tribunal fédéral rappelle les principes applicables à l'appréciation des preuves médicales, notamment le rôle des médecins, la libre appréciation des preuves et la valeur probante des expertises administratives et des rapports des médecins traitants.",
      "b_propositions": ["P1", "P2"]
    },
    {
      "a_text": "La juridiction cantonale a constaté que le rapport d'expertise de CEMEDEX S.A. remplissait les conditions nécessaires pour se voir reconnaître une pleine valeur probante.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Le Tribunal fédéral rejette les griefs de l'assuré concernant l'appréciation arbitraire des preuves et la violation du principe inquisitoire.",
      "b_propositions": ["P4", "P5"]
    },
    {
      "a_text": "Le Tribunal fédéral précise que la qualification de l'événement accidentel de rixe ou de chute n'a pas d'incidence sur la capacité de travail pertinente en matière d'assurance-invalidité.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "Le Tribunal fédéral confirme que la juridiction cantonale pouvait renoncer à ordonner une expertise supplémentaire et qu'une mesure de réadaptation sous forme de stage d'observation n'était pas nécessaire.",
      "b_propositions": ["P7", "P8"]
    },
    {
      "a_text": "L'assuré ne démontre pas que l'appréciation des experts serait arbitraire ou que le marché du travail équilibré ne comporterait pas d'activités adaptées à ses limitations fonctionnelles.",
      "b_propositions": ["P4", "P8"]
    }
  ]
}
